g=[[6,8,8,8,8,1,8,8,8,8],[8,8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,1,1,1],[1,8,8,8,8,8,8,1,1,1],[1,1,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8],[8,8,8,8,8,1,1,1,8,8]]
R=C=10
# flood 4-neighbor component of 8s from adjacent 6 seed
from collections import deque
q=deque([(0,0)]); seen={(0,0)}
while q:
 r,c=q.popleft()
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  rr,cc=r+dr,c+dc
  if 0<=rr<R and 0<=cc<C and (rr,cc) not in seen and g[rr][cc]==8:
   seen.add((rr,cc)); q.append((rr,cc))
out=[row[:] for row in g]
for r,c in seen:
 if g[r][c]!=8: continue
 boundary=False
 for dr in [-1,0,1]:
  for dc in [-1,0,1]:
   if dr==dc==0: continue
   rr,cc=r+dr,c+dc
   if not (0<=rr<R and 0<=cc<C) or (rr,cc) not in seen:
    boundary=True
 if boundary: out[r][c]=7
print('seen',len(seen))
print('\n'.join(' '.join(map(str,row)) for row in out))

# identify 4-connected 1 components touching grid edge; mark as blocked
ones={(r,c) for r in range(R) for c in range(C) if g[r][c]==1}
seen1=set(); eligible=set()
for p in ones:
 if p in seen1: continue
 comp={p}; seen1.add(p); qq=deque([p]); touches=False
 while qq:
  r,c=qq.popleft(); touches |= (r in (0,R-1) or c in (0,C-1))
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   z=(r+dr,c+dc)
   if z in ones and z not in seen1: seen1.add(z); comp.add(z); qq.append(z)
 if touches: eligible |= comp
blocked=eligible
# flood from marker treating all non-barrier cells (including 6) passable
reach={(0,0)}; qq=deque([(0,0)])
while qq:
 r,c=qq.popleft()
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  z=(r+dr,c+dc); rr,cc=z
  if 0<=rr<R and 0<=cc<C and z not in blocked and z not in reach:
   reach.add(z); qq.append(z)
out2=[row[:] for row in g]
for r,c in reach:
 if g[r][c]!=8: continue
 if any(not(0<=r+dr<R and 0<=c+dc<C) or (r+dr,c+dc) in blocked for dr in [-1,0,1] for dc in [-1,0,1] if (dr,dc)!=(0,0)):
  out2[r][c]=7
print('eligible',sorted(eligible)); print('\n'.join(' '.join(map(str,row)) for row in out2))
